abstract final class AlmaSpacing {
  /// Sin separación, dentro de componentes compactos.
  static const double space0 = 0.0;
  /// Ajustes finos dentro de inputs.
  static const double space2 = 2.0;
  /// Relleno del lado del ícono en botones; separaciones dentro de inputs.
  static const double space4 = 4.0;
  /// Unidad base; gutter y spacing del grid móvil.
  static const double space8 = 8.0;
  /// Relleno horizontal de botón; offset del grid móvil.
  static const double space16 = 16.0;
  /// Separación entre grupos pequeños.
  static const double space24 = 24.0;
  /// Separación entre bloques.
  static const double space32 = 32.0;
  /// Separación entre secciones pequeñas.
  static const double space40 = 40.0;
  /// Separación entre secciones.
  static const double space48 = 48.0;
  /// Espacio alrededor de objetos grandes.
  static const double space56 = 56.0;
  /// Espacio alrededor de objetos grandes.
  static const double space64 = 64.0;
  /// Espacio alrededor de objetos muy grandes.
  static const double space72 = 72.0;
  /// Máximo de la escala.
  static const double space80 = 80.0;
}

abstract final class AlmaRadius {
  /// El radio base. Los demás radios salen de él: el botón lo toma entero y cada pieza lo toma hasta su tope. Para cambiar la forma de todo el sistema se cambia este valor y se corre npm run build.
  static const double radiusBase = 16.0;
  /// Etiquetas flotantes de campo, globos de ayuda y contornos de foco pequeños.
  static const double radiusChip = 8.0;
  /// Tarjetas de muestra de color.
  static const double radiusSwatch = 8.0;
  /// Menús, alertas y tarjetas de lista (en Figma: ProductCard y tarjetas de viaje).
  static const double radiusPanel = 16.0;
  /// Marcos de documentación y tarjetas grandes.
  static const double radiusCard = 16.0;
  /// Botones: Button, IconButton, Stepper, PopUpButton y SegmentedControl. 100 px es la píldora.
  static const double radiusButton = 16.0;
  /// Campos: TextInput, Textarea, Search y el campo del Slider.
  static const double radiusField = 16.0;
  /// Destinos de navegación: Tabs, Sidebar, ítems de menú y Breadcrumb.
  static const double radiusNav = 16.0;
  /// Tag, fichas del buscador, Badge y archivos del FileUploader.
  static const double radiusTag = 16.0;
  /// La casilla de Checkbox: siempre con esquinas, para no confundirla con Radio.
  static const double radiusCheckbox = 2.0;
  /// Formas siempre redondas: Switch, barra de progreso, días del calendario, íconos dentro de campos.
  static const double radiusPill = 100.0;
}

abstract final class AlmaBreakpoint {
  /// Móvil. 4 columnas (grid ALMA de Figma: columna 76, gutter 8, offset 16).
  static const double bpSm = 320.0;
  /// Tablet. 8 columnas, margen 16px, gutter 32px (IBM).
  static const double bpMd = 672.0;
  /// Escritorio. 16 columnas, margen 16px, gutter 32px (IBM).
  static const double bpLg = 1056.0;
  /// Escritorio ancho. 16 columnas, margen 16px (IBM).
  static const double bpXlg = 1312.0;
  /// Máximo: el contenido deja de crecer. 16 columnas, margen 24px (IBM).
  static const double bpMax = 1584.0;
}

abstract final class AlmaSize {
  /// Área táctil mínima de todo control (Apple HIG 44 pt; supera WCAG 2.2 AA de 24 px). Si el control se ve más chico, su área de toque se amplía hasta 44.
  static const double sizeTouchMin = 44.0;
  /// Alto de control en densidad compacta: Button sm, SegmentedControl, PopUpButton, menús, Tabs, Sidebar, SearchField, Checkbox, Switch y áreas de toque de íconos. Supera los 24 px de WCAG 2.2 AA.
  static const double sizeControlCompact = 32.0;
  /// Alto de TextInput y Stepper en densidad normal.
  static const double sizeField = 56.0;
  /// Alto de TextInput y Stepper en densidad compacta.
  static const double sizeFieldCompact = 40.0;
  /// Alto de fila de Table en densidad normal.
  static const double sizeRow = 56.0;
  /// Alto de fila de Table en densidad compacta. Table dense usa el alto de control (44 o 32 px).
  static const double sizeRowCompact = 40.0;
}

abstract final class AlmaIconSize {
  /// El de los componentes: botones, menús, campos, navegación, avisos y datos. Va a 16 px de su texto.
  static const double iconSizeSm = 16.0;
  /// Íconos sueltos fuera de un componente, junto a texto de lectura.
  static const double iconSizeMd = 20.0;
  /// Íconos sueltos junto a títulos o en piezas destacadas.
  static const double iconSizeLg = 24.0;
  /// Zonas vacías o para soltar archivos, y piezas destacadas.
  static const double iconSizeXl = 32.0;
}

abstract final class AlmaGrid {
  /// Columnas en móvil.
  static const double gridColumnsMobile = 4.0;
  /// Ancho de columna en móvil.
  static const double gridColumnMobile = 76.0;
  /// Gutter en móvil.
  static const double gridGutterMobile = 8.0;
  /// Margen lateral en móvil.
  static const double gridOffsetMobile = 16.0;
  /// Columnas desde bp-md (IBM).
  static const double gridColumnsMd = 8.0;
  /// Columnas desde bp-lg (IBM).
  static const double gridColumnsLg = 16.0;
  /// Gutter desde bp-md: 16px a cada lado de la columna (IBM 2x Grid).
