abstract final class AlmaFontAxis {
  /// Ancho de Roboto Flex (eje wdth, de 25 a 151). ALMA usa 130: extendida, sin llegar al máximo de la fuente (151). Antes 150, 151 y 125.
  static const double fontWidth = 130.0;
  /// Grado de Roboto Flex (eje GRAD, de −200 a 150): engrosa o aligera el trazo sin cambiar el ancho del texto, así nada se mueve de lugar. ALMA usa 20, un poco sobre el neutro (0). Antes 0 y −200.
  static const double fontGrade = 20.0;
}

abstract final class AlmaFontWeight {
  /// Titulares display (web-display-*, app-display-*, print-display-*).
  static const double fontWeightDisplay = 220.0;
  /// Encabezados (h1–h6, headline, title, citas) y títulos de componentes: Card, Alert, Modal, Toolbar, Accordion y otros.
  static const double fontWeightHeading = 350.0;
  /// Cuerpo y etiquetas: todo el texto que no es título ni énfasis, dentro y fuera de los componentes.
  static const double fontWeightBody = 350.0;
  /// Énfasis dentro de un componente: la opción elegida, la página actual, insignias, títulos de grupo, enlaces sueltos y texto en negrita.
  static const double fontWeightEmphasis = 500.0;
}

